macro.command:
// Abjure the Extraplanar – Channel Divinity macro
// Foundry v12.331 + dnd5e v4.3.9
// Requires: Midi-QOL, DAE

if (!token) return ui.notifications.warn("Select your token.");

const caster = token.actor;
const saveDC = caster.system.attributes.spelldc;
const DIST = 30;
const VALID = ["aberration", "celestial", "elemental", "fey", "fiend"];

// 1️⃣ Find your Channel Divinity item on the caster
const cdItem = caster.items.find(i => i.name === "引導神力：驅散異域 Channel Divinity： Abjure The Extraplanar.");
if (!cdItem) return ui.notifications.error("No 'Channel Divinity' item found.");

// 2️⃣ Pick the correct embedded effect on that item
//    (for example: the third effect—adjust index as needed)
const itemEffectData = cdItem.effects.contents[0]; 
if (!itemEffectData) return ui.notifications.error("The item has no effects to apply.");

// 3️⃣ Prepare the effect data to apply later
const baseEffectData = itemEffectData.toObject();
delete baseEffectData._id;

// 4️⃣ Locate targets within range
const targets = canvas.tokens.placeables.filter(t => {
  if (!t.actor || t === token) return false;
  if (t.actor.system.attributes.hp.value <= 0) return false;
  if (!VALID.includes(t.actor.system.details.type.value)) return false;
  return canvas.grid.measureDistance(token, t) <= DIST;
});

if (!targets.length) {
  return ChatMessage.create({ content: "No valid extraplanar creatures within 30 ft." });
}

let chatHtml = `<h2>${caster.name} uses Abjure the Extraplanar</h2><ul>`;

for (let tgt of targets) {
  // Skip actors who already have the effect
  const existing = tgt.actor.effects.find(e => e.origin === cdItem.uuid && e.label === baseEffectData.label);
  if (existing) {
    chatHtml += `<li>${tgt.name}: ❌ Already has ${baseEffectData.label}</li>`;
    continue;
  }

  const roll = await tgt.actor.rollAbilitySave("wis", { chatMessage: false, fastForward: true });
  const failed = roll.total < saveDC;
  chatHtml += `<li>${tgt.name}: ${failed ? "❌ Failed" : "✅ Success"} (rolled ${roll.total} vs DC ${saveDC})</li>`;

  if (failed) {
    // Clone effect, set new origin, and apply
    const eff = duplicate(baseEffectData);
    eff.origin = cdItem.uuid;
    await tgt.actor.createEmbeddedDocuments("ActiveEffect", [eff]);
  }
}

chatHtml += "</ul>";
ChatMessage.create({ content: chatHtml });
